// <auto-generated />
using LiveScore.Shared;
namespace LiveScore.WebApi.Features.Notifications
{
    using System.Collections.Generic;
    using System.Threading.Tasks;
    using LiveScore.Features.Matches.Models;
    using LiveScore.Soccers.Features.Matches;
    using Microsoft.AspNetCore.Mvc;

    [Route("api/[controller]")]
    [ApiController]
    public class NotificationController : ControllerBase
    {
        private IMatchPushEventHandler soccerPushEventHandler;

        public NotificationController(IMatchPushEventHandler soccerPushEventHandler)
        {
            this.soccerPushEventHandler = soccerPushEventHandler;
        }

        [HttpPost("PushMatchEvent")]
        public async Task PushMatchEvent(
            int sportId,
            [FromBody]Dictionary<string, MatchPushEvent> pushEvents)
        {
            if (sportId == SportConstants.SoccerId && pushEvents != null)
            {
                await soccerPushEventHandler.Handle(pushEvents);
            }
        }
    }
}
